Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:700">Carnot cycle guide</span>
<label>Carnot cycle step <select id="cycleStepInput" onchange="update_cycleStep(this.value)"><option>Step 1: M→N</option><option>Step 2: N→O</option><option>Step 3: O→P</option><option>Step 4: P→M</option></select></label>
<label><input id="thermalConditionInput" type="checkbox" onchange="toggle_thermalCondition(this.checked)"> <span id="thermalConditionVal">Thermal contact: isothermal</span></label>
<label><input id="representationInput" type="checkbox" onchange="toggle_representation(this.checked)"> <span id="representationVal">Piston panels</span></label>
<span id="demoNarration" style="display:block;margin:0;font-size:10px;max-width:180px;line-height:1.25"></span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 980, H = 520;
draw.viewbox(0, 0, W, H);

var current = {
  cycleStep: 'Step 1: M→N',
  thermalCondition: 'Thermal contact: isothermal',
  representation: 'Piston panels'
};

var demoIndex = 0;
var demoSteps = [
  {
    title: 'Step 1: Hot isothermal expansion',
    narration: 'The gas is in thermal contact with the hot reservoir at temperature Tₕ. Heat Qₕ enters the gas while the piston rises, so the gas expands from M to N and does work on the surroundings.',
    state: { cycleStep: 'Step 1: M→N', thermalCondition: 'Thermal contact: isothermal', representation: 'Piston panels' }
  },
  {
    title: 'Step 2: Adiabatic expansion',
    narration: 'The gas continues expanding from N to O, but now it is insulated. No heat arrow appears because the energy change comes from work during expansion, not heat transfer.',
    state: { cycleStep: 'Step 2: N→O', thermalCondition: 'Insulated: adiabatic', representation: 'Piston panels' }
  },
  {
    title: 'Step 3: Cold isothermal compression',
    narration: 'The gas is placed in contact with the cold reservoir at temperature T꜀. The piston is pushed downward, compressing the gas from O to P while heat Q꜀ leaves the gas.',
    state: { cycleStep: 'Step 3: O→P', thermalCondition: 'Thermal contact: isothermal', representation: 'Piston panels' }
  },
  {
    title: 'Step 4: Adiabatic compression',
    narration: 'The gas is insulated again and compressed from P back to M. With no heat transfer, work done on the gas restores it to the starting state of the cycle.',
    state: { cycleStep: 'Step 4: P→M', thermalCondition: 'Insulated: adiabatic', representation: 'Piston panels' }
  },
  {
    title: 'Map the pistons to the p-V loop',
    narration: 'Switching to the p-V path shows the same four processes as four connected curve segments. The active step highlights the matching segment, making the closed cycle M→N→O→P→M visible.',
    state: { cycleStep: 'Step 1: M→N', thermalCondition: 'Thermal contact: isothermal', representation: 'p-V path' }
  }
];

var stepNames = ['Step 1: M→N', 'Step 2: N→O', 'Step 3: O→P', 'Step 4: P→M'];
var stepInfo = [
  { n: 1, proc: 'Isothermal', action: 'expansion', path: '(M→N)', block: 'Reservoir', temp: '(Temperature Tₕ)', kind: 'hot', gasH: 70, workDir: 'up', heat: 'Qₕ', heatDir: 'up' },
  { n: 2, proc: 'Adiabatic', action: 'expansion', path: '(N→O)', block: 'Insulation', temp: '', kind: 'ins', gasH: 138, workDir: 'up', heat: null },
  { n: 3, proc: 'Isothermal', action: 'compression', path: '(O→P)', block: 'Reservoir', temp: '(Temperature T꜀)', kind: 'cold', gasH: 138, workDir: 'down', heat: 'Q꜀', heatDir: 'down' },
  { n: 4, proc: 'Adiabatic', action: 'compression', path: '(P→M)', block: 'Insulation', temp: '', kind: 'ins', gasH: 62, workDir: 'down', heat: null }
];

function stepIndex() {
  return Math.max(0, stepNames.indexOf(current.cycleStep));
}

function textHalo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}

function label(g, str, x, y, size, anchor, weight) {
  var t = g.text(str).font({ family: 'Arial, Helvetica, sans-serif', size: size || 20, anchor: anchor || 'middle', weight: weight || 'normal' }).fill('#000').move(x, y);
  textHalo(t);
  return t;
}

function multiLabel(g, lines, x, y, size, weights) {
  for (var i = 0; i < lines.length; i++) {
    label(g, lines[i], x, y + i * (size + 5), size, 'middle', weights && weights[i] ? weights[i] : 'normal');
  }
}

function arrow(g, x1, y1, x2, y2, color, width, title, popupTitle, popupBody) {
  var a = g.group();
  a.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var len = 16 + width * 0.9;
  var spread = 0.55;
  var p1 = [x2, y2];
  var p2 = [x2 - len * Math.cos(ang - spread), y2 - len * Math.sin(ang - spread)];
  var p3 = [x2 - len * Math.cos(ang + spread), y2 - len * Math.sin(ang + spread)];
  a.polygon([p1, p2, p3].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color).stroke('none');
  if (title) {
    a.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(title, e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () { showPopup(popupTitle || title, popupBody || title); });
  }
  return a;
}

function drawGasDots(g, x, y, w, h, active) {
  var clip = draw.clip().add(draw.rect(w, h).move(x, y));
  var dotGroup = g.group().clipWith(clip);
  var r = active ? 2.7 : 2.3;
  for (var yy = y + 12; yy < y + h - 5; yy += 16) {
    for (var xx = x + 10; xx < x + w - 6; xx += 15) {
      var dx = ((Math.round(xx + yy) % 3) - 1) * 2;
      dotGroup.circle(r * 2).center(xx + dx, yy).fill(active ? '#5f6669' : '#7d8588');
    }
  }
}

function drawCylinder(g, cx, baseY, gasH, active) {
  var cw = 66;
  var gasY = baseY - gasH;
  g.rect(cw, gasH).move(cx - cw / 2, gasY).fill('#d5d8d8').stroke({ color: active ? '#59646c' : '#81898c', width: active ? 2.2 : 1.5 });
  drawGasDots(g, cx - cw / 2, gasY, cw, gasH, active);
  g.rect(cw + 4, 17).move(cx - cw / 2 - 2, gasY - 17).fill('#eef3f7').stroke({ color: active ? '#7b8fa6' : '#a7b4c5', width: active ? 2 : 1.3 });
  g.line(cx, gasY - 17, cx, gasY - 48).stroke({ color: active ? '#8192c7' : '#aeb8d4', width: active ? 8 : 6, linecap: 'butt' });
  g.line(cx, gasY - 17, cx, gasY - 48).stroke({ color: '#eef1fb', width: 3, linecap: 'butt' });
}

function drawPanel(info, idx, active) {
  var x = [0, 260, 520, 780][idx];
  var top = 0, bw = 190, bh = 360;
  var g = draw.group();
  g.opacity(active ? 1 : 0.52);

  var fill = info.kind === 'hot' ? '#efb5b5' : (info.kind === 'cold' ? '#a9cad8' : '#f5d9cb');
  var border = info.kind === 'hot' ? '#e28181' : (info.kind === 'cold' ? '#5597ad' : '#777b7d');
  g.rect(bw, bh).move(x, top).fill(fill).stroke({ color: border, width: 2.2 });

  if (active) {
    g.rect(bw - 5, bh - 5).move(x + 2.5, top + 2.5).fill('none').stroke({ color: '#f1b400', width: 5, opacity: 0.9 });
    g.rect(bw - 14, bh - 14).move(x + 7, top + 7).fill('#fff7c2').opacity(0.11).stroke('none');
  }

  label(g, info.block, x + bw / 2, 314, 22, 'middle', 'normal');
  if (info.temp) label(g, info.temp, x + bw / 2, 348, 20, 'middle', 'normal');

  var cx = x + bw / 2;
  var baseY = 254;
  drawCylinder(g, cx, baseY, info.gasH, active);

  var pistonTop = baseY - info.gasH - 48;
  var green = active ? '#6ea23a' : '#8db463';
  var gray = active ? '#696f73' : '#8b8f92';

  if (info.workDir === 'up') {
    arrow(g, cx - 18, pistonTop + 42, cx - 18, pistonTop - 12, green, active ? 4 : 3, 'Work arrow: expansion work is done by the gas.', 'Work during expansion', 'During the two expansion steps the piston rises. The work arrow points outward from the gas because the gas does work on its surroundings.');
    label(g, 'W' + ['₁', '₂', '₃', '₄'][idx], cx - 34, pistonTop - 28, 22, 'start', 'normal');
  } else {
    arrow(g, cx - 18, pistonTop - 26, cx - 18, pistonTop + 30, green, active ? 4 : 3, 'Work arrow: compression work is done on the gas.', 'Work during compression', 'During the two compression steps the piston is pushed downward. The surroundings do work on the gas.');
    label(g, 'W' + ['₁', '₂', '₃', '₄'][idx], cx - 30, pistonTop - 45, 22, 'start', 'normal');
  }

  if (info.heat && info.heatDir === 'up') {
    arrow(g, cx, baseY + 39, cx, baseY + 7, gray, active ? 7 : 5, 'Heat crosses the gas boundary only in a reservoir-contact isothermal step.', 'Hot isothermal heat transfer', 'In Step 1 the gas touches the hot reservoir. Heat Qₕ enters the gas while the temperature remains Tₕ.');
    label(g, info.heat, cx - 15, baseY + 45, 20, 'middle', 'normal');
  }
  if (info.heat && info.heatDir === 'down') {
    arrow(g, cx, baseY - 5, cx, baseY + 37, gray, active ? 7 : 5, 'Heat crosses the gas boundary only in a reservoir-contact isothermal step.', 'Cold isothermal heat transfer', 'In Step 3 the gas touches the cold reservoir. Heat Q꜀ leaves the gas while the temperature remains T꜀.');
    label(g, info.heat, cx - 14, baseY + 43, 20, 'middle', 'normal');
  }

  var capLines = ['Step ' + info.n + ':', info.proc, info.action, info.path];
  multiLabel(g, capLines, x + bw / 2, 391, 21, ['bold', null, null, null]);

  g.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      var heatText = info.heat ? 'Heat transfer occurs here because the gas is touching a reservoir.' : 'No heat transfer: insulation makes this step adiabatic.';
      showTooltip('Step ' + info.n + ': ' + info.proc.toLowerCase() + ' ' + info.action + '. ' + heatText, e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      current.cycleStep = stepNames[idx];
      current.thermalCondition = (idx === 0 || idx === 2) ? 'Thermal contact: isothermal' : 'Insulated: adiabatic';
      applyUi();
      render();
      showPopup('Step ' + info.n + ': ' + info.proc + ' ' + info.action, (info.heat ? 'This isothermal reservoir-contact step allows heat to cross the gas boundary. ' : 'This insulated adiabatic step has no heat transfer. ') + 'It corresponds to the path segment ' + info.path + ' in the Carnot loop.');
    });
}

function drawPanels() {
  var active = stepIndex();
  for (var i = 0; i < stepInfo.length; i++) drawPanel(stepInfo[i], i, i === active);
}

function segmentPath(name) {
  var d = {
    MN: 'M270,145 C350,116 445,145 535,205',
    NO: 'M535,205 C590,233 640,292 660,358',
    OP: 'M660,358 C560,398 435,362 350,310',
    PM: 'M350,310 C303,260 235,205 270,145'
  };
  return d[name];
}

function triangleAt(g, x, y, angle, color) {
  var s = 12;
  var pts = [
    [x + s * Math.cos(angle), y + s * Math.sin(angle)],
    [x + s * Math.cos(angle + 2.45), y + s * Math.sin(angle + 2.45)],
    [x + s * Math.cos(angle - 2.45), y + s * Math.sin(angle - 2.45)]
  ];
  return g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
}

function drawPV() {
  var g = draw.group();

  g.line(150, 420, 150, 70).stroke({ color: '#222', width: 3, linecap: 'round' });
  g.line(150, 420, 790, 420).stroke({ color: '#222', width: 3, linecap: 'round' });
  triangleAt(g, 150, 61, -Math.PI / 2, '#222');
  triangleAt(g, 802, 420, 0, '#222');
  label(g, 'p', 126, 62, 26, 'middle', 'bold');
  label(g, 'V', 812, 432, 26, 'middle', 'bold');

  var names = ['MN', 'NO', 'OP', 'PM'];
  var activeName = ['MN', 'NO', 'OP', 'PM'][stepIndex()];
  var segLabel = {
    MN: 'M→N: isothermal at Tₕ; heat Qₕ enters.',
    NO: 'N→O: adiabatic expansion; no heat transfer.',
    OP: 'O→P: isothermal at T꜀; heat Q꜀ leaves.',
    PM: 'P→M: adiabatic compression; no heat transfer.'
  };
  var popupBody = {
    MN: 'The upper curve is the hot isotherm. The gas expands from M to N while receiving heat from the hot reservoir.',
    NO: 'This connecting curve is adiabatic expansion. Insulation prevents heat transfer while the volume continues to increase.',
    OP: 'The lower curve is the cold isotherm. Compression from O to P rejects heat to the cold reservoir.',
    PM: 'This adiabatic compression closes the cycle, returning the gas from P to M without heat transfer.'
  };

  for (var i = 0; i < names.length; i++) {
    var nm = names[i];
    var base = g.path(segmentPath(nm)).fill('none').stroke({ color: '#30363a', width: 3.2, linecap: 'round' });
    base.css('cursor', 'pointer')
      .on('mousemove', (function (txt) { return function (e) { showTooltip(txt, e); }; })(segLabel[nm]))
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', (function (n) { return function () { showPopup('Carnot segment ' + n, popupBody[n]); }; })(nm));
  }
  g.path(segmentPath(activeName)).fill('none').stroke({ color: '#f1b400', width: 8, linecap: 'round', opacity: 0.95 });
  g.path(segmentPath(activeName)).fill('none').stroke({ color: '#1f5f8b', width: 3.3, linecap: 'round' });

  triangleAt(g, 410, 151, 0.25, '#30363a');
  triangleAt(g, 610, 274, 1.05, '#30363a');
  triangleAt(g, 510, 370, 3.02, '#30363a');
  triangleAt(g, 288, 232, -2.12, '#30363a');

  label(g, 'M', 252, 118, 24, 'middle', 'bold');
  label(g, 'N', 551, 188, 24, 'middle', 'bold');
  label(g, 'O', 681, 355, 24, 'middle', 'bold');
  label(g, 'P', 331, 318, 24, 'middle', 'bold');

  label(g, 'isothermal at Tₕ', 404, 107, 20, 'middle', 'normal');
  label(g, 'adiabatic', 666, 259, 20, 'middle', 'normal');
  label(g, 'isothermal at T꜀', 516, 405, 20, 'middle', 'normal');
  label(g, 'adiabatic', 261, 258, 20, 'middle', 'normal');

  var lx = 790, ly = 92;
  g.rect(155, 88).move(lx - 12, ly - 14).fill('#fff').opacity(0.82).stroke({ color: '#c9ced3', width: 1 });
  arrow(g, lx, ly + 6, lx + 44, ly + 6, '#7aa642', 4, 'Green arrows represent work transfer at the piston.', 'Work arrows', 'Work arrows show whether the piston motion is expansion work by the gas or compression work on the gas.');
  label(g, 'work', lx + 76, ly - 5, 16, 'start', 'normal');
  arrow(g, lx, ly + 48, lx + 44, ly + 48, '#72787c', 6, 'Gray arrows represent heat transfer across the gas boundary.', 'Heat arrows', 'Heat arrows appear only on the two isothermal reservoir-contact parts of the cycle.');
  label(g, 'heat', lx + 76, ly + 37, 16, 'start', 'normal');

  var activeText = [
    'Active: M→N, hot isothermal expansion',
    'Active: N→O, adiabatic expansion',
    'Active: O→P, cold isothermal compression',
    'Active: P→M, adiabatic compression'
  ][stepIndex()];
  label(g, activeText, 470, 462, 22, 'middle', 'bold');
}

function render() {
  draw.clear();
  if (current.representation === 'p-V path') drawPV();
  else drawPanels();
}

function applyUi() {
  var cycle = document.getElementById('cycleStepInput');
  var therm = document.getElementById('thermalConditionInput');
  var rep = document.getElementById('representationInput');
  if (cycle) cycle.value = current.cycleStep;
  if (therm) therm.checked = current.thermalCondition === 'Insulated: adiabatic';
  if (rep) rep.checked = current.representation === 'p-V path';
  var thermVal = document.getElementById('thermalConditionVal');
  var repVal = document.getElementById('representationVal');
  if (thermVal) thermVal.textContent = current.thermalCondition;
  if (repVal) repVal.textContent = current.representation;
}

function update_cycleStep(v) {
  current.cycleStep = v;
  var i = stepIndex();
  current.thermalCondition = (i === 0 || i === 2) ? 'Thermal contact: isothermal' : 'Insulated: adiabatic';
  applyUi();
  render();
}

function toggle_thermalCondition(on) {
  current.thermalCondition = on ? 'Insulated: adiabatic' : 'Thermal contact: isothermal';
  var i = stepIndex();
  if (on && (i === 0 || i === 2)) current.cycleStep = 'Step 2: N→O';
  if (!on && (i === 1 || i === 3)) current.cycleStep = 'Step 1: M→N';
  applyUi();
  render();
}

function toggle_representation(on) {
  current.representation = on ? 'p-V path' : 'Piston panels';
  applyUi();
  render();
}

function updateDemoText() {
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (n) n.textContent = demoSteps[demoIndex].narration;
  if (l) l.textContent = (demoIndex + 1) + '/' + demoSteps.length;
}

function applyDemoStep() {
  var s = demoSteps[demoIndex].state;
  current.cycleStep = s.cycleStep;
  current.thermalCondition = s.thermalCondition;
  current.representation = s.representation;
  applyUi();
  updateDemoText();
  render();
}

function prevStep() {
  demoIndex = (demoIndex + demoSteps.length - 1) % demoSteps.length;
  applyDemoStep();
}

function nextStep() {
  demoIndex = (demoIndex + 1) % demoSteps.length;
  applyDemoStep();
}

applyDemoStep();
window.__markRendered();
// @FIGURE_CODE_END

