  drawGasDots(g, cx - cw / 2, gasY, cw, gasH, active);
  g.rect(cw + 4, 17).move(cx - cw / 2 - 2, gasY - 17).fill('#eef3f7').stroke({ color: active ? '#7b8fa6' : '#a7b4c5', width: active ? 2 : 1.3 });
  g.line(cx, gasY - 17, cx, gasY - 48).stroke({ color: active ? '#8192c7' : '#aeb8d4', width: active ? 8 : 6, linecap: 'butt' });
  g.line(cx, gasY - 17, cx, gasY - 48).stroke({ color: '#eef1fb', width: 3, linecap: 'butt' });
}

function drawPanel(info, idx, active) {
  var x = [0, 260, 520, 780][idx];
  var top = 0, bw = 190, bh = 360;
  var g = draw.group();
  g.opacity(active ? 1 : 0.52);

  var fill = info.kind === 'hot' ? '#efb5b5' : (info.kind === 'cold' ? '#a9cad8' : '#f5d9cb');
  var border = info.kind === 'hot' ? '#e28181' : (info.kind === 'cold' ? '#5597ad' : '#777b7d');
  g.rect(bw, bh).move(x, top).fill(fill).stroke({ color: border, width: 2.2 });

  if (active) {
    g.rect(bw - 5, bh - 5).move(x + 2.5, top + 2.5).fill('none').stroke({ color: '#f1b400', width: 5, opacity: 0.9 });
    g.rect(bw - 14, bh - 14).move(x + 7, top + 7).fill('#fff7c2').opacity(0.11).stroke('none');
  }

  label(g, info.block, x + bw / 2, 314, 22, 'middle', 'normal');
  if (info.temp) label(g, info.temp, x + bw / 2, 348, 20, 'middle', 'normal');

  var cx = x + bw / 2;
  var baseY = 254;
  drawCylinder(g, cx, baseY, info.gasH, active);

  var pistonTop = baseY - info.gasH - 48;
  var green = active ? '#6ea23a' : '#8db463';
  var gray = active ? '#696f73' : '#8b8f92';

  if (info.workDir === 'up') {
    arrow(g, cx - 18, pistonTop + 42, cx - 18, pistonTop - 12, green, active ? 4 : 3, 'Work arrow: expansion work is done by the gas.', 'Work during expansion', 'During the two expansion steps the piston rises. The work arrow points outward from the gas because the gas does work on its surroundings.');
    label(g, 'W' + ['₁', '₂', '₃', '₄'][idx], cx - 34, pistonTop - 28, 22, 'start', 'normal');
  } else {
    arrow(g, cx - 18, pistonTop - 26, cx - 18, pistonTop + 30, green, active ? 4 : 3, 'Work arrow: compression work is done on the gas.', 'Work during compression', 'During the two compression steps the piston is pushed downward. The surroundings do work on the gas.');
    label(g, 'W' + ['₁', '₂', '₃', '₄'][idx], cx - 30, pistonTop - 45, 22, 'start', 'normal');
  }

  if (info.heat && info.heatDir === 'up') {
    arrow(g, cx, baseY + 39, cx, baseY + 7, gray, active ? 7 : 5, 'Heat crosses the gas boundary only in a reservoir-contact isothermal step.', 'Hot isothermal heat transfer', 'In Step 1 the gas touches the hot reservoir. Heat Qₕ enters the gas while the temperature remains Tₕ.');
    label(g, info.heat, cx - 15, baseY + 45, 20, 'middle', 'normal');
  }
  if (info.heat && info.heatDir === 'down') {
    arrow(g, cx, baseY - 5, cx, baseY + 37, gray, active ? 7 : 5, 'Heat crosses the gas boundary only in a reservoir-contact isothermal step.', 'Cold isothermal heat transfer', 'In Step 3 the gas touches the cold reservoir. Heat Q꜀ leaves the gas while the temperature remains T꜀.');
    label(g, info.heat, cx - 14, baseY + 43, 20, 'middle', 'normal');
  }

  var capLines = ['Step ' + info.n + ':', info.proc, info.action, info.path];
  multiLabel(g, capLines, x + bw / 2, 391, 21, ['bold', null, null, null]);

  g.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      var heatText = info.heat ? 'Heat transfer occurs here because the gas is touching a reservoir.' : 'No heat transfer: insulation makes this step adiabatic.';
      showTooltip('Step ' + info.n + ': ' + info.proc.toLowerCase() + ' ' + info.action + '. ' + heatText, e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      current.cycleStep = stepNames[idx];
      current.thermalCondition = (idx === 0 || idx === 2) ? 'Thermal contact: isothermal' : 'Insulated: adiabatic';
      applyUi();
      render();
      showPopup('Step ' + info.n + ': ' + info.proc + ' ' + info.action, (info.heat ? 'This isothermal reservoir-contact step allows heat to cross the gas boundary. ' : 'This insulated adiabatic step has no heat transfer. ') + 'It corresponds to the path segment ' + info.path + ' in the Carnot loop.');
    });
}

function drawPanels() {
  var active = stepIndex();
  for (var i = 0; i < stepInfo.length; i++) drawPanel(stepInfo[i], i, i === active);
}

function segmentPath(name) {
  var d = {
    MN: 'M270,145 C350,116 445,145 535,205',
    NO: 'M535,205 C590,233 640,292 660,358',
    OP: 'M660,358 C560,398 435,362 350,310',
    PM: 'M350,310 C303,260 235,205 270,145'
  };
  return d[name];
}

function triangleAt(g, x, y, angle, color) {
  var s = 12;
  var pts = [
    [x + s * Math.cos(angle), y + s * Math.sin(angle)],
    [x + s * Math.cos(angle + 2.45), y + s * Math.sin(angle + 2.45)],
    [x + s * Math.cos(angle - 2.45), y + s * Math.sin(angle - 2.45)]
  ];
  return g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
}

function drawPV() {
  var g = draw.group();

  g.line(150, 420, 150, 70).stroke({ color: '#222', width: 3, linecap: 'round' });
  g.line(150, 420, 790, 420).stroke({ color: '#222', width: 3, linecap: 'round' });
  triangleAt(g, 150, 61, -Math.PI / 2, '#222');
  triangleAt(g, 802, 420, 0, '#222');
  label(g, 'p', 126, 62, 26, 'middle', 'bold');
  label(g, 'V', 812, 432, 26, 'middle', 'bold');

  var names = ['MN', 'NO', 'OP', 'PM'];
  var activeName = ['MN', 'NO', 'OP', 'PM'][stepIndex()];
  var segLabel = {
    MN: 'M→N: isothermal at Tₕ; heat Qₕ enters.',
    NO: 'N→O: adiabatic expansion; no heat transfer.',
    OP: 'O→P: isothermal at T꜀; heat Q꜀ leaves.',
    PM: 'P→M: adiabatic compression; no heat transfer.'
  };
  var popupBody = {
    MN: 'The upper curve is the hot isotherm. The gas expands from M to N while receiving heat from the hot reservoir.',
    NO: 'This connecting curve is adiabatic expansion. Insulation prevents heat transfer while the volume continues to increase.',
    OP: 'The lower curve is the cold isotherm. Compression from O to P rejects heat to the cold reservoir.',
    PM: 'This adiabatic compression closes the cycle, returning the gas from P to M without heat transfer.'
  };

  for (var i = 0; i < names.length; i++) {
    var nm = names[i];
    var base = g.path(segmentPath(nm)).fill('none').stroke({ color: '#30363a', width: 3.2, linecap: 'round' });
    base.css('cursor', 'pointer')
      .on('mousemove', (function (txt) { return function (e) { showTooltip(txt, e); }; })(segLabel[nm]))
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', (function (n) { return function () { showPopup('Carnot segment ' + n, popupBody[n]); }; })(nm));
  }
  g.path(segmentPath(activeName)).fill('none').stroke({ color: '#f1b400', width: 8, linecap: 'round', opacity: 0.95 });
  g.path(segmentPath(activeName)).fill('none').stroke({ color: '#1f5f8b', width: 3.3, linecap: 'round' });

  triangleAt(g, 410, 151, 0.25, '#30363a');
  triangleAt(g, 610, 274, 1.05, '#30363a');
  triangleAt(g, 510, 370, 3.02, '#30363a');
  triangleAt(g, 288, 232, -2.12, '#30363a');

  label(g, 'M', 252, 118, 24, 'middle', 'bold');
  label(g, 'N', 551, 188, 24, 'middle', 'bold');
  label(g, 'O', 681, 355, 24, 'middle', 'bold');
  label(g, 'P', 331, 318, 24, 'middle', 'bold');

  label(g, 'isothermal at Tₕ', 404, 107, 20, 'middle', 'normal');
  label(g, 'adiabatic', 666, 259, 20, 'middle', 'normal');
  label(g, 'isothermal at T꜀', 516, 405, 20, 'middle', 'normal');
  label(g, 'adiabatic', 261, 258, 20, 'middle', 'normal');

  var lx = 790, ly = 92;
  g.rect(155, 88).move(lx - 12, ly - 14).fill('#fff').opacity(0.82).stroke({ color: '#c9ced3', width: 1 });
  arrow(g, lx, ly + 6, lx + 44, ly + 6, '#7aa642', 4, 'Green arrows represent work transfer at the piston.', 'Work arrows', 'Work arrows show whether the piston motion is expansion work by the gas or compression work on the gas.');
  label(g, 'work', lx + 76, ly - 5, 16, 'start', 'normal');
  arrow(g, lx, ly + 48, lx + 44, ly + 48, '#72787c', 6, 'Gray arrows represent heat transfer across the gas boundary.', 'Heat arrows', 'Heat arrows appear only on the two isothermal reservoir-contact parts of the cycle.');
  label(g, 'heat', lx + 76, ly + 37, 16, 'start', 'normal');

  var activeText = [
    'Active: M→N, hot isothermal expansion',
    'Active: N→O, adiabatic expansion',
    'Active: O→P, cold isothermal compression',
    'Active: P→M, adiabatic compression'
  ][stepIndex()];
  label(g, activeText, 470, 462, 22, 'middle', 'bold');
}

function render() {
  draw.clear();
  if (current.representation === 'p-V path') drawPV();
  else drawPanels();
}

function applyUi() {
  var cycle = document.getElementById('cycleStepInput');
  var therm = document.getElementById('thermalConditionInput');
  var rep = document.getElementById('representationInput');
  if (cycle) cycle.value = current.cycleStep;
  if (therm) therm.checked = current.thermalCondition === 'Insulated: adiabatic';
  if (rep) rep.checked = current.representation === 'p-V path';
  var thermVal = document.getElementById('thermalConditionVal');
  var repVal = document.getElementById('representationVal');
  if (thermVal) thermVal.textContent = current.thermalCondition;
  if (repVal) repVal.textContent = current.representation;
}

function update_cycleStep(v) {
  current.cycleStep = v;
  var i = stepIndex();
  current.thermalCondition = (i === 0 || i === 2) ? 'Thermal contact: isothermal' : 'Insulated: adiabatic';
  applyUi();
  render();
}

function toggle_thermalCondition(on) {
  current.thermalCondition = on ? 'Insulated: adiabatic' : 'Thermal contact: isothermal';
  var i = stepIndex();
  if (on && (i === 0 || i === 2)) current.cycleStep = 'Step 2: N→O';
  if (!on && (i === 1 || i === 3)) current.cycleStep = 'Step 1: M→N';
  applyUi();
  render();
}

function toggle_representation(on) {
  current.representation = on ? 'p-V path' : 'Piston panels';
  applyUi();
  render();
}

function updateDemoText() {
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (n) n.textContent = demoSteps[demoIndex].narration;
  if (l) l.textContent = (demoIndex + 1) + '/' + demoSteps.length;
}

function applyDemoStep() {
  var s = demoSteps[demoIndex].state;
  current.cycleStep = s.cycleStep;
  current.thermalCondition = s.thermalCondition;
  current.representation = s.representation;
  applyUi();
  updateDemoText();
  render();
}

function prevStep() {
  demoIndex = (demoIndex + demoSteps.length - 1) % demoSteps.length;
  applyDemoStep();
}

function nextStep() {
  demoIndex = (demoIndex + 1) % demoSteps.length;
  applyDemoStep();
}

applyDemoStep();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A Carnot engine cycle proceeds through four fixed piston processes: hot isothermal expansion absorbs heat, adiabatic expansion transfers no heat, cold isothermal compression rejects heat, and adiabatic compression returns the gas to its starting state.
KEY INSIGHT (what students should walk away understanding): The two reservoir-contact steps exchange heat at constant temperature, while the two insulated steps exchange no heat and connect the hot and cold isotherms to complete the Carnot cycle.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A Carnot engine cycle proceeds through four fixed piston processes: hot isothermal expansion absorbs heat, adiabatic expansion transfers no heat, cold isothermal compression rejects heat, and adiabatic compression returns the gas to its starting state.",
  "figureType": "diagram",
  "elements": [
    "four equal-sized cylinder-and-piston panels arranged left to right across the figure",
    "Step 1 panel label/caption 'Step 1: Isothermal expansion (M→N)'",
    "Step 1 hot reservoir block below the cylinder, colored red or orange-red, labeled 'Reservoir' and '(Temperature Th)'",
    "Step 1 cylinder outline with piston, vertical piston stem, and gray dotted gas region at a relatively small starting volume",
    "Step 1 heat arrow labeled 'Qh' showing heat entering the gas from the hot reservoir",
    "Step 1 work arrow labeled 'W1' showing work done by the expanding gas as the piston moves upward",
    "Step 2 panel label/caption 'Step 2: Adiabatic expansion (N→O)'",
    "Step 2 insulation block below the cylinder, colored pale tan or peach, labeled 'Insulation'",
    "Step 2 cylinder outline with piston, vertical piston stem, and gray dotted gas region at a larger volume than Step 1",
    "Step 2 work arrow labeled 'W2' showing work done by the expanding gas as the piston moves upward",
    "Step 3 panel label/caption 'Step 3: Isothermal compression (O→P)'",
    "Step 3 cold reservoir block below the cylinder, colored blue, labeled 'Reservoir' and '(Temperature Tc)'",
    "Step 3 cylinder outline with piston, vertical piston stem, and gray dotted gas region at a large volume",
    "Step 3 heat arrow labeled 'Qc' showing heat leaving the gas to the cold reservoir",
    "Step 3 work arrow labeled 'W3' showing work done on the gas as the piston is pushed downward",
    "Step 4 panel label/caption 'Step 4: Adiabatic compression (P→M)'",
    "Step 4 insulation block below the cylinder, colored pale tan or peach, labeled 'Insulation'",
    "Step 4 cylinder outline with piston, vertical piston stem, and gray dotted gas region at the smallest final volume",
    "Step 4 work arrow labeled 'W4' showing work done on the gas as the piston is pushed downward",
    "optional nonintrusive selected-step explanation box that appears only after a step is selected",
    "optional subtle selected-step marker or underline that appears only after a step is selected and does not dim or fade any other panel",
    "optional small p-V inset hidden by default, with pressure axis labeled p, volume axis labeled V, closed clockwise Carnot loop labeled M, N, O, P, and segment labels for isothermal and adiabatic processes"
  ],
  "interactions": [
    {
      "id": "selectedStep",
      "type": "state",
      "label": "Explain step",
      "states": [
        "Overview",
        "Step 1: M→N",
        "Step 2: N→O",
        "Step 3: O→P",
        "Step 4: P→M"
      ],
      "default": "Overview",
      "teaches": "Each selected step has a fixed thermal contact condition, piston motion, heat-transfer direction, and work direction; selecting a step explains these relationships without changing the four-panel source composition"
    },
    {
      "id": "pvInset",
      "type": "toggle",
      "label": "Show small p-V inset",
      "default": false,
      "teaches": "The four piston panels correspond to the four segments of a closed clockwise path on a pressure-volume diagram, but the piston sequence remains the primary representation"
    }
  ],
  "demo_steps": [
    {
      "title": "Source-style overview",
      "narration": "All four panels are shown equally, matching the static textbook composition. The reservoirs, insulation blocks, heat arrows, work arrows, and captions together show the full Carnot sequence at once.",
      "state": {
        "selectedStep": "Overview",
        "pvInset": false
      }
    },
    {
      "title": "Step 1: hot isothermal expansion",
      "narration": "The gas touches the hot reservoir at temperature Th. Heat Qh enters while the gas expands from M to N and does work W1 as the piston rises.",
      "state": {
        "selectedStep": "Step 1: M→N",
        "pvInset": false
      }
    },
    {
      "title": "Step 2: adiabatic expansion",
      "narration": "The gas is insulated, so no heat arrow appears. The gas continues expanding from N to O and does work W2 while cooling because energy leaves through work rather than heat.",
      "state": {
        "selectedStep": "Step 2: N→O",
        "pvInset": false
      }
    },
    {
      "title": "Step 3: cold isothermal compression",
      "narration": "The gas touches the cold reservoir at temperature Tc. Work W3 is done on the gas as the piston moves downward, and heat Qc leaves the gas to the cold reservoir.",
      "state": {
        "selectedStep": "Step 3: O→P",
        "pvInset": false
      }
    },
    {
      "title": "Step 4: adiabatic compression",
      "narration": "The gas is insulated again, so there is no heat transfer. Work W4 is done on the gas, compressing it from P back to M and completing the cycle.",
      "state": {
        "selectedStep": "Step 4: P→M",
        "pvInset": false
      }
    },
    {
      "title": "Optional p-V connection",
      "narration": "Turning on the small p-V inset shows that the same four physical steps form a closed clockwise loop M→N→O→P→M, while the piston panels remain the main view.",
      "state": {
        "selectedStep": "Overview",
        "pvInset": true
      }
    }
  ],
  "keyInsight": "The two reservoir-contact steps exchange heat at constant temperature, while the two insulated steps exchange no heat and connect the hot and cold isotherms to complete the Carnot cycle.",
  "reconstructionNotes": "Keep the default view source-like: four equal panels fill the available width, all at full opacity, with no default active-step outline, no yellow glow, and no fading of inactive panels. Use generous spacing so Step 4 caption is not truncated and lower reservoir/insulation labels do not crowd the bottom edge. Make W labels, Q labels, reservoir temperature text, and step captions large enough to read at inline scale; place labels close to their arrows or blocks but not overlapping cylinder parts. Preserve the original-style color hierarchy: hot reservoir red/orange-red, cold reservoir blue, insulation pale tan/peach, piston/cylinder neutral gray, gas gray dotted. Use only a subtle selected-step underline, small marker, or adjacent explanation callout after the learner chooses a step; do not recolor the whole panel or alter the apparent source figure. Keep the p-V loop hidden by default and, when enabled, render it as a small secondary inset rather than replacing or visually competing with the four piston panels."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.

systemPrompt:
You are a strict critic of generated inline-interactive 2D figures (SVG.js / Chart.js / Mermaid) against the original 2D textbook figure image.
You will receive the original source figure image, the generated HTML/JavaScript code, and a rendered screenshot of the generated HTML (if screenshot capture succeeds). Start by using the screenshot to help evaluate the faithfulness of the generated figure to the source figure, listing discrepancies in the primitive elements between what you see in the source figure versus what you see in the generated figure. If the screenshot was not received, mention this in the notes.
Score the generated figure using the rubric and give feedback to improve the figure. Be critical and honest — err toward lower scores when in doubt. The default (step-0) state should read as a drop-in replacement for the static source image. Do not give credit for things that are absent or barely present. Output ONLY a valid JSON object — no explanation, no markdown, no fences.

AUTOMATED VERIFICATION ALREADY PASSED. A deterministic verifier has rendered this figure headless at multiple viewports and confirmed it runs without exceptions or page errors, produces a visible visual root (SVG, canvas, or Mermaid diagram) containing real text or graphics rather than an empty frame, and fits the viewport with no horizontal overflow and the main visual unclipped at wide widths.
Spend NO scores, failure modes, discrepancies, or action items on any of that. Focus ENTIRELY on SEMANTIC FIDELITY to the source: correct 2D structure, correct mark types, faithful composition and colors, correct and meaningful labels, meaningful and conceptually-correct interactions, and concept accuracy. Judge whether it is the *right* figure and a good teaching artifact — not whether it renders.
IMPORTANT — the 2D verifier performs NO label checks at all: no on-screen check, no size check, no overlap check. Label placement is fully IN SCOPE for you. Do flag labels that collide with each other or the artwork, escape the plot area, are clipped at the edge, or are too small to read comfortably at inline size.

SCAFFOLD CONTEXT (provided automatically — do not penalise for missing these):
- SVG.js v3, Chart.js v4, Mermaid v11 and expr-eval are preloaded; #container, window.__markRendered() and the 'fig-resize' event are pre-wired
- #ui is an auto-docking control panel; setUiLayout(...) positions it
- showPopup(...), showTooltip(...), hideTooltip() — built-in explainer and tooltip affordances
- Plotting helpers: setPlotFrame(...), plotX(...) / plotY(...) for data→pixel mapping, plotFunction(...), fillBetween(...), plotParametric(...), integrateSimpson(...), findRoot(...)
- compileExpr(...) and bindEquationInput(...) — live user-editable equation inputs
- Generated code may add controls, panels, and UI affordances as needed to support the planned interactions

DISCREPANCIES - list 0-6 visual discrepancies between the source figure and the generated figure, prioritized by impact on recognizability and concept accuracy
- Focus on: wrong mark types, missing or incorrect elements, wrong colors, missing or mislabeled annotations, broken or absent interactions
- De-prioritize: exact crop/zoom, whitespace variation, small differences in font face or padding — only flag these if they make the figure hard to recognize or misleading
- For multipanel source figures, if the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), check the HTML/JS before flagging a part as "missing" — a part hidden behind an unactivated toggle is not a discrepancy

FAILURE MODES — list any that apply (use empty array [] if none):
"Missing-Labels"          — important text annotations are absent
"Wrong-Primitives"        — incorrect geometric shapes used for the concept
"Interaction-Broken"      — interactive controls are present but non-functional
"Interaction-Missing"     — no meaningful interactions beyond pan/zoom or hover tooltips
"Scale-Wrong"             — element proportions are noticeably off
"Color-Wrong"             — colors don't match the original figure
"Hallucination"           — elements present that do not appear in the original
"Concept-Misunderstood"   — the core concept being illustrated is    misrepresented

SCORES — integer 1–5 for each field:
geometry_accuracy — Judge 2D structural fidelity against the source: axis ranges, tick marks and gridlines, the shape and trend of the data, node-and-edge topology and counts, relative proportions and layout, and line styling (dashed vs solid, stroke weight, arrowheads, fill vs outline). Flag "Wrong-Primitives" and cap the score when a major element uses the wrong mark type — e.g. a scatter drawn as a connected line, a bar chart drawn as an area, a directed edge drawn without its arrowhead, a smooth curve drawn as straight segments. This is a 2D figure: do NOT penalise the absence of depth, perspective, or a 3D vantage point.
  5 – All elements represented; plausible positions, connections, proportions
  4 – All major elements present; minor position/alignment issues
  3 – 1-2 elements missing OR noticeable spatial errors; concept still recognizable
  2 – Multiple missing elements OR major spatial errors
  1 – Unrecognizable or completely wrong topology

interactivity_usability — CRITICAL: panning or zooming the figure does NOT count as an interaction, and a hover tooltip on its own is weak. Meaningful interactions = sliders, toggles, buttons, demo-step players, equation inputs, or code-editor workbenches built by the developer, whose handlers actually redraw the figure.
  5 – All planned interactions functional and pedagogically useful; count matches figure complexity (1 deep slider is correct for a single-variable concept; 3+ expected for multi-step figures); demo steps present if the plan includes them
  4 – Most planned interactions functional; minor usability issues; pedagogical value clear
  3 – At least one meaningful interaction works; some planned interactions missing or broken; or interactions only weakly connected to the concept
  2 – Interactions exist in code but broken or no visible effect
  1 – Only pan/zoom or a bare hover tooltip present, or no interactions at all — score MUST be 1

faithfulness — Judge overall visual resemblance to the source — composition, geometry, and color scheme at a glance — rather than an exhaustive checklist of small differences. For multipanel source figures where the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), it is correct and expected for only one part to be visible in the default screenshot; check the HTML/JS for a toggle control before penalizing a currently-hidden part as missing or absent. Do not over-penalize extra elements added beyond the source (additional UI chrome, decorative touches) unless they clutter the figure or change its overall look — flag those under the Hallucination failure mode rather than cutting this score for minor additions.
  5 – Clearly recognizable as the same figure: correct geometry, colors, composition, and major labels all present
  4 – Recognizable at a glance; minor differences in color, proportion, or label placement
  3 – General idea clear but notable differences in geometry, composition, or missing elements
  2 – Hard to recognize as the same figure; significant content differences
  1 – Completely different or fabricated

label_quality — Label placement is NOT screened by the verifier for 2D figures — judge it fully. Judge CONTENT (right labels present, correct text, on the correct element, matching the source), PLACEMENT (collisions with each other or the artwork, escaping the plot area, clipping at the edge), and LEGIBILITY (comfortably readable at inline size, with a deliberate hierarchy — primary labels standing out over axis labels — matching what the source implies).
  5 – All the right labels present, correct text on the correct elements, matching the source, cleanly placed without collisions, AND sized/styled for easy legibility with a clear hierarchy matching the source
  4 – Content correct; only 1-2 minor issues (content, placement, OR sizing/hierarchy — e.g. a label slightly too small, or one mild collision)
  3 – Half of labels have issues, whether content (wrong text, wrong target, missing, unclear), placement (overlapping, escaping the plot area, clipped), or legibility (uncomfortably small, inconsistent hierarchy)
  2 – Most labels problematic — mislabeled/missing content, badly colliding, or generally too small/cluttered to read comfortably
  1 – No labels, or all wrong/mislabeled/illegible

concept_accuracy:
  5 – All concepts accurate; interactions demonstrate correct relationships; no misinformation
  4 – Main concept correct; ≤1 minor detail wrong or missing
  3 – Main concept present; 2-3 details wrong or missing
  2 – Significant errors or fabrications; would mislead students
  1 – Completely incorrect or misleading

ACTION ITEMS — separate feedback for the generation and the plan:
- action_items: list 2-4 generation-level fixes (broken controls, wrong primitives, missing labels, scale issues, camera/view correction — things fixable without changing the plan)
- plan_action_items: list 0-2 plan-level fixes (wrong projection_type, missing core elements, wrong interaction type for the concept, fundamental misunderstanding — things requiring a revised plan). Use [] if the plan is sound.

Output this exact JSON structure and nothing else:
{
  "discrepancies": [],
  "failure_modes": [],
  "geometry_accuracy": 3,
  "interactivity_usability": 3,
