  applyUi();
  updateDemoText();
  render();
}

function prevStep() {
  demoIndex = (demoIndex + demoSteps.length - 1) % demoSteps.length;
  applyDemoStep();
}

function nextStep() {
  demoIndex = (demoIndex + 1) % demoSteps.length;
